package ai.wazir.mobile.network

import ai.wazir.mobile.domain.ParsedPairingUri
import java.net.URI
import java.net.URLDecoder

object PairingUriParser {
    /**
     * Parses and validates a `wazir://pair?...` QR payload generated by `wa mobile pair`.
     * Rejects payloads that are missing short-lived session parameters or attempt to embed
     * permanent operator tokens.
     */
    fun parse(rawUri: String): Result<ParsedPairingUri> {
        val trimmed = rawUri.trim()
        if (trimmed.isEmpty()) {
            return Result.failure(IllegalArgumentException("Pairing URI cannot be empty"))
        }

        val uri = try {
            URI(trimmed)
        } catch (e: Exception) {
            return Result.failure(IllegalArgumentException("Malformed pairing URI: ${e.message}", e))
        }

        if (!uri.scheme.equals("wazir", ignoreCase = true) || !uri.host.equals("pair", ignoreCase = true)) {
            return Result.failure(IllegalArgumentException("Invalid pairing URI scheme or host; expected wazir://pair"))
        }

        val params = parseQueryParams(uri.rawQuery.orEmpty())
        if (params.containsKey("operatorToken") || params.containsKey("token") || params.containsKey("apiKey")) {
            return Result.failure(
                SecurityException("Pairing URI must not contain a permanent operator token")
            )
        }

        val sessionId = params["sessionId"]?.trim().orEmpty()
        val secret = params["secret"]?.trim().orEmpty()
        if (sessionId.length < 6 || secret.length < 16) {
            return Result.failure(
                IllegalArgumentException("Pairing URI is missing valid sessionId or short-lived pairing secret")
            )
        }

        val name = params["name"]?.trim()?.takeIf { it.isNotEmpty() } ?: "Wazir Controller"
        val rawUrl = params["url"]?.trim()?.takeIf { it.isNotEmpty() }
        val validatedUrl = if (rawUrl != null) {
            validateControllerBaseUrl(rawUrl, allowLoopbackHttp = true).getOrElse { err ->
                return Result.failure(err)
            }
        } else {
            null
        }

        val fingerprint = params["fp"]?.trim()?.takeIf { it.isNotEmpty() }
        val apiVersion = params["v"]?.trim()?.takeIf { it.isNotEmpty() } ?: "1.0.0"

        return Result.success(
            ParsedPairingUri(
                sessionId = sessionId,
                pairingSecret = secret,
                controllerName = name,
                controllerUrl = validatedUrl,
                tlsCertFingerprint = fingerprint,
                apiVersion = apiVersion,
            )
        )
    }

    /**
     * Enforces HTTPS for remote controllers. Cleartext HTTP is only permitted for local loopback
     * (`127.0.0.1`, `localhost`, `::1`, or Android emulator loopback `10.0.2.2`) when explicitly
     * allowed for local development/testing.
     */
    fun validateControllerBaseUrl(rawUrl: String, allowLoopbackHttp: Boolean = true): Result<String> {
        val trimmed = rawUrl.trim().trimEnd('/')
        if (trimmed.isEmpty()) {
            return Result.failure(IllegalArgumentException("Controller URL cannot be empty"))
        }

        val uri = try {
            URI(trimmed)
        } catch (e: Exception) {
            return Result.failure(IllegalArgumentException("Invalid controller URL: ${e.message}", e))
        }

        val scheme = uri.scheme?.lowercase()
            ?: return Result.failure(IllegalArgumentException("Controller URL must include https:// scheme"))
        val host = uri.host?.lowercase()
            ?: return Result.failure(IllegalArgumentException("Controller URL must include a valid host"))

        if (scheme == "https") {
            return Result.success(trimmed)
        }

        if (scheme == "http") {
            val isLoopback = host == "localhost" ||
                host == "127.0.0.1" ||
                host == "::1" ||
                host == "[::1]" ||
                host == "10.0.2.2"
            if (allowLoopbackHttp && isLoopback) {
                return Result.success(trimmed)
            }
            return Result.failure(
                SecurityException("Insecure HTTP is not allowed for remote controllers ($host). Use HTTPS.")
            )
        }

        return Result.failure(IllegalArgumentException("Unsupported URL scheme '$scheme'. Use https://"))
    }

    private fun parseQueryParams(rawQuery: String): Map<String, String> {
        if (rawQuery.isBlank()) return emptyMap()
        val result = LinkedHashMap<String, String>()
        for (pair in rawQuery.split("&")) {
            if (pair.isBlank()) continue
            val idx = pair.indexOf('=')
            if (idx < 0) {
                val key = URLDecoder.decode(pair, Charsets.UTF_8.name())
                result[key] = ""
            } else {
                val key = URLDecoder.decode(pair.substring(0, idx), Charsets.UTF_8.name())
                val value = URLDecoder.decode(pair.substring(idx + 1), Charsets.UTF_8.name())
                result[key] = value
            }
        }
        return result
    }
}
